              "type": "line",
              "speaker": "mara_kell",
              "speakerLabel": "Mara Kell",
              "text": "Water on the plate. Chain groaning. That shackle forward, still not seized.",
              "html": "Water on the plate. Chain groaning. That shackle forward, still not seized.",
