              "id": "ch01.s04.b009",
              "type": "line",
              "speaker": "sella_rourke",
              "speakerLabel": "Sella Rourke",
              "text": "Report to me before you go ashore. I like to know where my people are.",
              "html": "Report to me before you go ashore. I like to know where my people are.",
